using System.Text.Json; using Confluent.Kafka;
namespace SurgeLab.Api;
public class KafkaProducer:IKafkaProducer{private readonly string _bs; public KafkaProducer(IConfiguration c){_bs=c["Kafka:BootstrapServers"]??"kafka:29092";} public async Task PublishAsync(string topic,object payload){var cfg=new ProducerConfig{BootstrapServers=_bs,Acks=Acks.All}; using var p=new ProducerBuilder<string,string>(cfg).Build(); var r=await p.ProduceAsync(topic,new Message<string,string>{Key=Guid.NewGuid().ToString(),Value=JsonSerializer.Serialize(payload)}); Console.WriteLine($"[Apache Kafka] {topic} offset={r.Offset}");}}
public class SurgeService:ISurgeService{private readonly IRideStore _s; public SurgeService(IRideStore s){_s=s;} public Task<SurgeReport> ReportAsync(){var all=_s.All(); var dt=all.Where(x=>x.Zone=="Downtown" && x.Weather=="Rain").ToList(); int demand=dt.Count>0?120:20; int supply=dt.Count>0?10:15; double ratio=(double)demand/supply; double mult=ratio>=10?2.5:ratio>=5?2.0:ratio>=2?1.5:1.0; return Task.FromResult(new SurgeReport(all,demand,supply,Math.Round(ratio,1),mult,20*mult,DateTime.UtcNow));}}
public class AnalystAgentService:IAnalystAgent{public Task<object> AnalyzeAsync(SurgeReport r){string narrative=$"Downtown: SURGE {r.SurgeMultiplier}x - Demand {r.DowntownDemand}, Supply {r.DowntownSupply}, Ratio {r.Ratio}. Rain + 5pm rush hour. Normal price $20 -> surge ${r.SurgePrice}. Without surge, wait would be ~38 min, 90 people stranded. With surge, drivers move downtown, wait ~4 min. Recommendation: Apply {r.SurgeMultiplier}x now, notify drivers in Suburb, re-check in 5 min (sliding window)."; return Task.FromResult<object>(new{Summary=$"SURGE {r.SurgeMultiplier}x Downtown: {r.DowntownDemand} demand / {r.DowntownSupply} supply = {r.Ratio}x, price ${r.SurgePrice}", r.DowntownDemand, r.DowntownSupply, r.Ratio, r.SurgeMultiplier, r.SurgePrice, AnalystNarrative=narrative, Recommendation=$"Apply {r.SurgeMultiplier}x now", r.GeneratedAt});}}
